1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Records a soft-duplicate match before {@link SaveOwner} runs. The create has already
9	 * passed {@link CheckUniqueIdentity}, so it is not a hard duplicate. When it still shares
10	 * an existing owner's lastName (compared case-insensitively with collapsed whitespace)
11	 * and postcode but carries a different telephone, the matched owner's id is stored on
12	 * {@code possibleDuplicateOf}, which surfaces as {@code possibleDuplicate}/{@code
13	 * possibleDuplicateOf} on the response. Left unset (so {@code possibleDuplicate} is false)
14	 * otherwise.
15	 */
16	public class FlagPossibleDuplicate {
17	
18	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
19	        String postcode = owner.getPostcode();
20	        if (postcode == null) {
21	            return;
22	        }
23	        String lastName = CheckUniqueHousehold.normalize(owner.getLastName());
24	        for (Owner other : ownerRepository.findAll()) {
25	            if (!other.getId().equals(owner.getId())
26	                    && postcode.equals(other.getPostcode())
27	                    && lastName.equals(CheckUniqueHousehold.normalize(other.getLastName()))
28	                    && !postcode.isBlank()
29	                    && !equalsTelephone(owner, other)) {
30	                owner.setPossibleDuplicateOf(other.getId());
31	                return;
32	            }
33	        }
34	    }
35	
36	    private static boolean equalsTelephone(Owner owner, Owner other) {
37	        String telephone = owner.getTelephone();
38	        return telephone != null && telephone.equals(other.getTelephone());
39	    }
40	}
